import React, { useEffect, useState } from 'react';
import {
  View,
  Text,
  Animated,
  StyleSheet,
  Pressable,
  ImageBackground,
  Easing,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { colors, spacing, borderRadius, typography, shadows } from '../theme';
import { Feather } from '@expo/vector-icons';

export interface FindingDriverScreenProps {
  readonly onCancel?: () => void;
  readonly onBack?: () => void;
}

const FindingDriverScreen: React.FC<FindingDriverScreenProps> = ({
  onCancel,
  onBack,
}) => {
  const [pulseAnim] = useState(new Animated.Value(0));
  const [progressAnim] = useState(new Animated.Value(0));

  useEffect(() => {
    // Pulse animation for the map pin
    Animated.loop(
      Animated.sequence([
        Animated.timing(pulseAnim, {
          toValue: 1,
          duration: 2000,
          easing: Easing.bezier(0.215, 0.61, 0.355, 1),
          useNativeDriver: true,
        }),
      ])
    ).start();

    // Indeterminate progress bar animation
    Animated.loop(
      Animated.timing(progressAnim, {
        toValue: 1,
        duration: 1500,
        easing: Easing.linear,
        useNativeDriver: false, // width/transform interpolation
      })
    ).start();
  }, [pulseAnim, progressAnim]);

  const pulseScale = pulseAnim.interpolate({
    inputRange: [0, 0.8, 1],
