import React, { useEffect, useState } from 'react';
import {
  View,
  Text,
  Animated,
  StyleSheet,
  Pressable,
  ImageBackground,
  Easing,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { colors, spacing, borderRadius, typography, shadows } from '../theme';
import { Feather } from '@expo/vector-icons';

export interface DriverFoundScreenProps {
  readonly onCancel?: () => void;
}

const DriverFoundScreen: React.FC<DriverFoundScreenProps> = ({
  onCancel,
}) => {
  const [pulseAnim] = useState(new Animated.Value(0));
  const [slideDownAnim] = useState(new Animated.Value(-100)); // for toast
  const [slideUpAnim] = useState(new Animated.Value(200)); // for bottom sheet
  const [spinAnim] = useState(new Animated.Value(0));

  useEffect(() => {
    // Pulse animation
    Animated.loop(
      Animated.timing(pulseAnim, {
        toValue: 1,
        duration: 2000,
        easing: Easing.bezier(0.215, 0.61, 0.355, 1),
        useNativeDriver: true,
      })
    ).start();

    // Spinner animation
    Animated.loop(
      Animated.timing(spinAnim, {
        toValue: 1,
        duration: 800,
        easing: Easing.linear,
        useNativeDriver: true,
      })
    ).start();

    // Entry animations
    Animated.parallel([
      Animated.timing(slideDownAnim, {
        toValue: 0,
        duration: 500,
        easing: Easing.bezier(0.16, 1, 0.3, 1),
        useNativeDriver: true,
      }),
      Animated.timing(slideUpAnim, {
        toValue: 0,
        duration: 600,
        easing: Easing.bezier(0.16, 1, 0.3, 1),
        useNativeDriver: true,
      }),
    ]).start();
  }, [pulseAnim, spinAnim, slideDownAnim, slideUpAnim]);

  const pulseScale = pulseAnim.interpolate({
    inputRange: [0, 1],
    outputRange: [0.8, 2],
  });

  const pulseOpacity = pulseAnim.interpolate({
    inputRange: [0, 1],
    outputRange: [0.5, 0],
  });

  const spin = spinAnim.interpolate({
    inputRange: [0, 1],
    outputRange: ['0deg', '360deg'],
  });

  return (
    <View style={styles.container}>
      {/* Map Canvas */}
      <ImageBackground
        source={{
          uri: 'https://lh3.googleusercontent.com/aida-public/AB6AXuCRyJWOKsY-us35wkUfj1u9xmtW8WeADcfnDr2SKfp7SirU_iZsNuLuIf7q9jz_HvPFlH8xBFF02XgRKuiB80nWx7jubAdsIXvyD_7h7NUjqjd-zTmqmCKhRkiZQ794igAbEFlpWPw69EYJy5suK7Fr5NMlsnkOdPybfxA8RHjfNQ1dR2-UqsYR10jyG-DHoZbgUevphbrwvC7w61w6Eko782nPjrl1CdVwaetvJMzCX3RrIdz7fwap',
        }}
        style={styles.mapCanvas}
        resizeMode="cover"
      />

      <SafeAreaView style={styles.overlayArea}>
        {/* Top Floating Toast */}
        <Animated.View
          style={[
            styles.toastContainer,
            { transform: [{ translateY: slideDownAnim }] },
          ]}
        >
          <View style={styles.toast}>
            <Feather name="check-circle" size={24} color={colors.primary} />
            <Text style={styles.toastText}>Driver Found!</Text>
          </View>
        </Animated.View>

        {/* Central Map Marker */}
        <View style={styles.markerWrapper}>
          <View style={styles.markerContainer}>
            <Animated.View
              style={[
                styles.pulseRing,
                {
                  transform: [{ scale: pulseScale }],
                  opacity: pulseOpacity,
                },
              ]}
            />
            <View style={styles.markerCenter}>
              <Feather name="truck" size={24} color={colors.onPrimary} />
            </View>
          </View>
        </View>

        {/* Bottom Spacer */}
        <View style={styles.flexSpacer} />

        {/* Bottom Sheet Expansion */}
        <Animated.View
          style={[
            styles.bottomSheetWrapper,
            { transform: [{ translateY: slideUpAnim }] },
          ]}
        >
          <View style={styles.bottomSheet}>
            {/* Handle */}
            <View style={styles.dragHandle} />

            <View style={styles.sheetContent}>
              {/* Status Row */}
              <View style={styles.statusRow}>
                <Animated.View style={[styles.spinner, { transform: [{ rotate: spin }] }]} />
                <View style={styles.statusTextCol}>
                  <Text style={styles.statusTitle}>Assigning driver to your trip...</Text>
                  <Text style={styles.statusSubtitle}>Matching you with the best vehicle nearby.</Text>
                </View>
              </View>

              {/* Fake Progress Bar */}
              <View style={styles.progressBarTrack}>
                <View style={styles.progressBarFill} />
              </View>

              {/* Cancel Button */}
              <Pressable
                style={styles.cancelButton}
                onPress={onCancel}
                accessibilityRole="button"
              >
                <Text style={styles.cancelButtonText}>Cancel Request</Text>
              </Pressable>
            </View>
          </View>
        </Animated.View>
      </SafeAreaView>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: colors.background,
  },
  mapCanvas: {
    ...StyleSheet.absoluteFillObject,
    zIndex: 0,
  },
  overlayArea: {
    flex: 1,
    zIndex: 10,
  },

  // Toast
  toastContainer: {
    alignItems: 'center',
    paddingTop: spacing.xl,
    paddingHorizontal: spacing.marginMobile,
    zIndex: 40,
  },
  toast: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: spacing.md,
    backgroundColor: colors.surfaceContainerLowest + 'F2', // 95% opacity
    paddingHorizontal: spacing.xl,
    paddingVertical: spacing.sm,
    borderRadius: borderRadius.full,
    borderWidth: 1,
    borderColor: colors.surfaceVariant,
    ...shadows.card,
  },
  toastText: {
    fontSize: typography.headlineSm.fontSize,
    fontWeight: typography.headlineSm.fontWeight,
    color: colors.onSurface,
    fontFamily: typography.headlineSm.fontFamily,
  },

  // Central Marker
  markerWrapper: {
    position: 'absolute',
