import React, { useState, useRef } from 'react';
import {
  View,
  Text,
  StyleSheet,
  Pressable,
  Image,
  TextInput,
  KeyboardAvoidingView,
  Platform,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { colors, spacing, borderRadius, typography, shadows } from '../theme';
import { Feather } from '@expo/vector-icons';
import { mockActiveTrip } from '../data/mockData';

export interface PickupOtpVerificationScreenProps {
  readonly onBack?: () => void;
  readonly onVerify?: (otp: string) => void;
  readonly onResend?: () => void;
}

const PickupOtpVerificationScreen: React.FC<PickupOtpVerificationScreenProps> = ({
  onBack,
  onVerify,
  onResend,
}) => {
  const [otp, setOtp] = useState(['', '', '', '']);
  const inputs = useRef<Array<TextInput | null>>([]);

  const handleOtpChange = (value: string, index: number) => {
    const newOtp = [...otp];
    newOtp[index] = value;
    setOtp(newOtp);

    // Auto-advance
    if (value && index < 3) {
      inputs.current[index + 1]?.focus();
    }
  };

  const handleKeyPress = (e: any, index: number) => {
    if (e.nativeEvent.key === 'Backspace' && !otp[index] && index > 0) {
      inputs.current[index - 1]?.focus();
    }
  };

  const isOtpComplete = otp.every((val) => val.length === 1);

  return (
    <SafeAreaView style={styles.safeArea} edges={['top', 'bottom']}>
      <KeyboardAvoidingView
        style={styles.keyboardAvoid}
        behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
      >
        {/* Top App Bar */}
        <View style={styles.header}>
          <Pressable
            style={styles.iconButton}
            onPress={onBack}
            accessibilityRole="button"
          >
            <Feather name="arrow-left" size={24} color={colors.onSurface} />
          </Pressable>
          <Text style={styles.headerTitle}>Pickup Verification</Text>
          <View style={{ width: 40 }} /> {/* Spacer */}
        </View>

        <View style={styles.content}>
          {/* Trip Context Card */}
          <View style={styles.contextCard}>
            <View style={styles.locationRow}>
              <View style={styles.locationIconContainer}>
                <Feather name="map-pin" size={20} color={colors.primary} />
              </View>
              <View>
                <Text style={styles.locationLabel}>Pickup Location</Text>
                <Text style={styles.locationText}>{mockActiveTrip.stops[0]?.address}</Text>
              </View>
            </View>

            <View style={styles.divider} />

            <View style={styles.driverRow}>
              <Image
                source={{ uri: 'https://lh3.googleusercontent.com/aida-public/AB6AXuC5Miy2__jGbN42AlpHhkRAUwlWZHbHDy6-hizTRk1dgDxkPKRqvK_Riuf2CKO-3ctNLxSvoTSIYbIhGBRC_Q1VZ3Ic0Go6pVlPq-lof32oczDBRrC3u6_rzL3bQALlL5IfYM7ppqOVxXDxAGf2JRIFaOIFYrXHQo5ap74W5szEc2U4Zx3mB3CpJNlsAZCxvxDdxTt17hMkylLfmWMXAYyndvLdt2iLljm3n5dAcPIVe9njt9DYYXd-7EbEl3M9maSE8g' }}
                style={styles.driverAvatar}
              />
              <View style={styles.driverInfo}>
                <Text style={styles.driverName}>{mockActiveTrip.driverName}</Text>
                <Text style={styles.driverSubtext}>
                  {mockActiveTrip.vehicleType} <Text style={{ color: colors.outlineVariant }}>•</Text> {mockActiveTrip.vehicleNumber}
                </Text>
              </View>
              <View style={styles.ratingBadge}>
                <Feather name="star" size={12} color={colors.onSurfaceVariant} />
                <Text style={styles.ratingText}>{mockActiveTrip.driverRating}</Text>
              </View>
            </View>
          </View>

          {/* OTP Section Container */}
          <View style={styles.otpSection}>
            <Text style={styles.otpTitle}>Share your OTP</Text>
            <Text style={styles.otpSubtitle}>
              Please share this 4-digit code with your driver or enter it below to verify and start your trip.
            </Text>

            <View style={styles.otpInputContainer}>
              {otp.map((digit, index) => (
                <TextInput
                  key={index}
                  ref={(ref) => (inputs.current[index] = ref)}
                  style={[styles.otpInput, digit ? styles.otpInputFilled : null]}
                  value={digit}
                  onChangeText={(val) => handleOtpChange(val, index)}
                  onKeyPress={(e) => handleKeyPress(e, index)}
                  keyboardType="number-pad"
                  maxLength={1}
                  selectTextOnFocus
                />
              ))}
            </View>
          </View>
        </View>

        {/* Action Buttons Container */}
        <View style={styles.actionContainer}>
          <Pressable
            style={[
              styles.verifyButton,
              isOtpComplete ? styles.verifyButtonActive : styles.verifyButtonInactive,
            ]}
            onPress={() => isOtpComplete && onVerify?.(otp.join(''))}
            disabled={!isOtpComplete}
          >
            <Text style={styles.verifyButtonText}>VERIFY PICKUP OTP</Text>
          </Pressable>

          <Pressable style={styles.resendButton} onPress={onResend}>
            <Text style={styles.resendButtonText}>Resend OTP</Text>
          </Pressable>
        </View>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
};

