import React, { useEffect, useRef } from 'react';
import {
  View,
  Text,
  StyleSheet,
  Animated,
  Easing,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { colors, spacing, borderRadius, typography, shadows } from '../theme';
import { Feather } from '@expo/vector-icons';

export interface PaymentProcessingScreenProps {
  readonly amount?: string;
}

const PaymentProcessingScreen: React.FC<PaymentProcessingScreenProps> = ({
  amount = '₹ 340.00', // Use mock default
}) => {
  const rotation = useRef(new Animated.Value(0)).current;
  const pulse = useRef(new Animated.Value(0)).current;

  useEffect(() => {
    // Spinner rotation
    Animated.loop(
      Animated.timing(rotation, {
        toValue: 1,
        duration: 2000,
        easing: Easing.linear,
        useNativeDriver: true,
      })
    ).start();

    // Pulse animation
    Animated.loop(
      Animated.sequence([
        Animated.timing(pulse, {
          toValue: 1,
          duration: 1000,
          easing: Easing.bezier(0.215, 0.61, 0.355, 1),
          useNativeDriver: true,
        }),
        Animated.timing(pulse, {
          toValue: 0,
          duration: 1000,
          easing: Easing.out(Easing.ease),
          useNativeDriver: true,
        }),
      ])
    ).start();
  }, [rotation, pulse]);

  const spin = rotation.interpolate({
    inputRange: [0, 1],
    outputRange: ['0deg', '360deg'],
  });

  const pulseScale = pulse.interpolate({
    inputRange: [0, 1],
    outputRange: [0.8, 1.5],
  });

  const pulseOpacity = pulse.interpolate({
    inputRange: [0, 1],
    outputRange: [0.5, 0],
  });

  return (
    <SafeAreaView style={styles.safeArea}>
      <View style={styles.container}>
        {/* Background Ambient Effect */}
        <View style={styles.ambientGlow} />

        <View style={styles.content}>
          {/* Amount Display */}
          <View style={styles.amountCard}>
            <Text style={styles.amountLabel}>AMOUNT</Text>
            <Text style={styles.amountText}>{amount}</Text>
          </View>

          {/* Enhanced Loading Visualizer */}
          <View style={styles.visualizerContainer}>
            {/* Outer Pulse Rings */}
            <Animated.View
              style={[
                styles.pulseRing,
                {
                  transform: [{ scale: pulseScale }],
                  opacity: pulseOpacity,
                },
              ]}
            />
            <Animated.View
              style={[
                styles.pulseRingDelayed,
                {
                  transform: [{ scale: pulseScale }],
                  opacity: pulseOpacity,
                  // We simulate delay via a second animated value ideally, 
                  // but for simplicity we rely on one pulse for mock. 
                  // A real implementation might use multiple animated values.
                },
              ]}
            />

            {/* Core Spinner */}
            <Animated.View style={[styles.spinnerRing, { transform: [{ rotate: spin }] }]}>
              {/* Using a partial border to simulate SVG stroke-dasharray */}
              <View style={styles.spinnerArc} />
            </Animated.View>

            {/* Center Icon */}
            <View style={styles.centerIcon}>
              <Feather name="credit-card" size={24} color={colors.primary} />
            </View>
          </View>

          {/* Typography & Status */}
          <View style={styles.textContainer}>
            <Text style={styles.title}>Processing Payment...</Text>
            <Text style={styles.subtitle}>
              Please do not close the app or hit the back button.
            </Text>
          </View>

          {/* Progress Indicator Dots */}
          <View style={styles.dotsContainer}>
            <View style={styles.dot} />
            <View style={styles.dot} />
            <View style={styles.dot} />
          </View>
        </View>
      </View>
    </SafeAreaView>
  );
};

