  readonly timerSeconds?: number;
  readonly onVerify?: (otp: string) => void;
  readonly onResend?: () => void;
  readonly onChangeNumber?: () => void;
  readonly onBack?: () => void;
  readonly isLoading?: boolean;
  readonly error?: string | null;
}

const OtpVerificationScreen: React.FC<OtpVerificationScreenProps> = ({
  phoneNumber = '+91 98765 43210',
  timerSeconds = 30,
  onVerify,
  onResend,
  onChangeNumber,
  onBack,
  isLoading = false,
  error = null,
}) => {
  const [otp, setOtp] = useState(['', '', '', '']);
  const inputRefs = useRef<Array<TextInput | null>>([null, null, null, null]);

  const handleOtpChange = (text: string, index: number) => {
    // Only allow numbers
    const cleanText = text.replace(/[^0-9]/g, '');

    if (cleanText.length > 0) {
      const newOtp = [...otp];
      newOtp[index] = cleanText[0];
      setOtp(newOtp);

      // Auto-advance
      if (index < 3) {
        inputRefs.current[index + 1]?.focus();
      }
    } else {
      const newOtp = [...otp];
      newOtp[index] = '';
      setOtp(newOtp);
    }
  };

  const handleKeyPress = (e: any, index: number) => {
    if (e.nativeEvent.key === 'Backspace' && otp[index] === '') {
      // Auto-focus previous on backspace if current is empty
      if (index > 0) {
        inputRefs.current[index - 1]?.focus();
      }
    }
  };

  const handleVerify = () => {
    const fullOtp = otp.join('');
    if (fullOtp.length === 4) {
      onVerify?.(fullOtp);
    }
  };

  const formatTimer = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <SafeAreaView style={styles.safeArea} edges={['top', 'bottom']}>
      {/* Top Navigation */}
      <View style={styles.header}>
        <Pressable style={styles.iconButton} onPress={onBack}>
          <Feather name="arrow-left" size={24} color={colors.onSurface} />
        </Pressable>
        <Text style={styles.headerTitle}>Driver Hub</Text>
        <View style={styles.iconButton} />
      </View>

      <ScrollView contentContainerStyle={styles.scrollContent} keyboardShouldPersistTaps="handled">
        {/* Header Section */}
        <View style={styles.titleSection}>
          <Text style={styles.title}>Verify Mobile Number</Text>
          <Text style={styles.subtitle}>
            Enter the 4-digit code sent to{'\n'}
            <Text style={styles.phoneNumber}>{phoneNumber}</Text>
          </Text>
        </View>

        {/* OTP Input Section */}
        <View style={styles.inputSection}>
          <View style={styles.otpContainer}>
            {[0, 1, 2, 3].map((index) => (
              <TextInput
                key={index}
                ref={(ref) => { inputRefs.current[index] = ref; }}
                style={[
                  styles.otpInput,
                  error ? styles.otpInputError : null,
                ]}
                value={otp[index]}
                onChangeText={(text) => handleOtpChange(text, index)}
                onKeyPress={(e) => handleKeyPress(e, index)}
                keyboardType="number-pad"
                maxLength={1}
                placeholder="-"
                placeholderTextColor={colors.onSurfaceVariant}
              />
            ))}
          </View>

          {error && (
            <Text style={styles.errorText}>{error}</Text>
          )}

          <View style={styles.linksContainer}>
            <Pressable onPress={onResend} disabled={timerSeconds > 0}>
              <Text style={[styles.resendLink, timerSeconds > 0 && styles.resendDisabled]}>
                Resend OTP ({formatTimer(timerSeconds)})
              </Text>
            </Pressable>
            <Pressable onPress={onChangeNumber}>
              <Text style={styles.changeLink}>Change Number</Text>
            </Pressable>
          </View>
        </View>

        {/* Actions */}
        <View style={styles.actionsContainer}>
          <Button
            label={isLoading ? 'VERIFYING...' : 'VERIFY'}
            onPress={handleVerify}
            variant="primary"
            fullWidth
            size="lg"
            disabled={otp.join('').length < 4 || isLoading}
            icon={isLoading ? <MaterialIcons name="loop" size={20} color={colors.onSurfaceVariant} /> : undefined}
          />
        </View>
      </ScrollView>
    </SafeAreaView>
  );
};

const styles = StyleSheet.create({
  safeArea: {
    flex: 1,
    backgroundColor: colors.background,
  },
  header: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingHorizontal: spacing.sm,
    height: spacing.rowHeightStandard,
    backgroundColor: colors.surface,
  },
  iconButton: {
    width: 40,
    height: 40,
    borderRadius: 20,
    backgroundColor: colors.surfaceContainer,
    alignItems: 'center',
    justifyContent: 'center',
  },
  headerTitle: {
    fontSize: typography.headlineSm.fontSize,
    fontWeight: typography.headlineSm.fontWeight,
    color: colors.onSurface,
    fontFamily: typography.headlineSm.fontFamily,
  },
  scrollContent: {
    flexGrow: 1,
    paddingHorizontal: spacing.marginMobile,
    paddingTop: spacing.xxxl * 2, // mt-24 approx
    paddingBottom: spacing.xxxl,
    alignItems: 'center',
  },
  titleSection: {
    alignItems: 'center',
    marginBottom: spacing.xxxl,
  },
  title: {
    fontSize: typography.headlineMd.fontSize,
    fontWeight: typography.headlineMd.fontWeight,
    color: colors.onSurface,
    fontFamily: typography.headlineMd.fontFamily,
    marginBottom: spacing.xs,
    textAlign: 'center',
  },
  subtitle: {
    fontSize: typography.bodyMd.fontSize,
    color: colors.onSurfaceVariant,
    fontFamily: typography.bodyMd.fontFamily,
    textAlign: 'center',
    lineHeight: 20,
  },
  phoneNumber: {
    fontWeight: '600',
    color: colors.onSurface,
  },
  inputSection: {
    width: '100%',
    alignItems: 'center',
    marginBottom: spacing.xxxl,
  },
  otpContainer: {
    flexDirection: 'row',
    justifyContent: 'center',
    gap: spacing.md,
    marginBottom: spacing.lg,
  },
  otpInput: {
    width: 56,
    height: 64,
    backgroundColor: colors.surfaceVariant,
    borderRadius: borderRadius.md,
    textAlign: 'center',
    fontSize: typography.headlineMd.fontSize,
    fontWeight: typography.headlineMd.fontWeight,
    color: colors.onSurface,
    fontFamily: typography.headlineMd.fontFamily,
    ...shadows.sm,
  },
  otpInputError: {
    backgroundColor: colors.errorContainer,
    color: colors.error,
    borderWidth: 1,
    borderColor: colors.error,
  },
  errorText: {
    fontSize: typography.labelSm.fontSize,
    color: colors.error,
    fontFamily: typography.labelSm.fontFamily,
    marginBottom: spacing.md,
    textAlign: 'center',
  },
  linksContainer: {
    alignItems: 'center',
    gap: spacing.sm,
  },
  resendLink: {
    fontSize: typography.labelSm.fontSize,
    fontWeight: typography.labelSm.fontWeight,
    color: colors.primary,
    fontFamily: typography.labelSm.fontFamily,
  },
  resendDisabled: {
    color: colors.onSurfaceVariant,
  },
  changeLink: {
    fontSize: typography.labelSm.fontSize,
    color: colors.onSurfaceVariant,
    fontFamily: typography.labelSm.fontFamily,
    textDecorationLine: 'underline',
  },
  actionsContainer: {
    width: '100%',
    maxWidth: 400,
  },
});

export default OtpVerificationScreen;

